ref_dict.th:1.1:
\begin{theorem}
\label{th:1.1} Assume that $a(x)$ is constant, $a(x)= a>0$ for all $x\in[0,R]$. Then:
\begin{enumerate}
\item[{\rm (a)}] For every $\l \in \mathbb{R}$, the problem \eqref{eq:1.1} has a unique positive solution, $L_{\l}\in \mc{C}^2([0,R);\R)$.
\item[{\rm (b)}] The map
$$
    \begin{array}{rcl} \R & \longrightarrow & \mc{C}([0,R);\R) \\
      \lambda & \mapsto & L_{\l}\end{array}
$$
is differentiable and point-wise increasing in $\l$.
\item[{\rm (c)}] One has that
$$
   \lim_{\l \uparrow \infty}L_{\l} = +\infty\;\;\hbox{uniformly in compact subsets of}\;\; [0,R),
$$
unless
$\mathcal{B} = \mathcal{D}$ at $x=0$, in which case $L_{\l}(0) = 0$ for all $\l \in \mathbb{R}$.
\item[{\rm (d)}] One has that
\begin{equation}
\lim_{\l \downarrow -\infty} L_{\l} = 0 \;\; \text{uniformly  in compact subsets of}\;\; [0,R).
\end{equation}
\end{enumerate}
\end{theorem}

ref_dict.th:1.2:
\begin{theorem}
\label{th:1.2}
Assume that $a(x)$ is continuous and positive in $[0,R]$. Then:
	\begin{enumerate}
		\item[{\rm (a)}] For every $\l\in\R$, \eqref{eq:1.1} possesses a minimal and a maximal positive solution, respectively denoted by $L^{\rm min}_{\l}$ and $L^{\rm max}_{\l}$, in the sense that any other positive solution $L$ of \eqref{eq:1.1} satisfies
	\begin{equation}
		\label{i.4}
		L^{\rm min}_{\l}(x) \leq L(x) \leq L^{\rm max}_{\l}(x) \quad \hbox{for all } x \in [0,R).
	\end{equation}
	\item[{\rm (b)}] As in Theorem \ref{th:1.1},
	\begin{equation}
		\label{i.5}
		\lim_{\l \uparrow +\infty} L^{\rm min}_{\l} = +\infty \;\;\hbox{uniformly in compact subsets of}\;\; [0,R),
	\end{equation}
unless  $\mathcal{B} = \mathcal{D}$ at $x=0$, in which case $L^{\rm min}_{\l}(0) = 0$ for all $\l \in \mathbb{R}$.
	\item[{\rm (c)}] As in Theorem \ref{th:1.1},
\begin{equation}
		\label{i.6}
		\lim_{\l \downarrow -\infty} L^{\rm max}_{\l} = 0 \;\; \hbox{uniformly in compact subsets of}\;\; [0,R).
	\end{equation}
\item[{\rm (d)}] If, in addition, $a$ is non-increasing in $[0,R]$, $\l \geq 0$ and $\mc{B} \in \{ \mc{D}, \mc{N}, \mc{R}_\b : \b <0 \}$, we have that $L^{\rm min}_{\l} = L^{\rm max}_{\l}$. Thus, in such cases, \eqref{eq:1.1} has a unique positive solution.
\end{enumerate}
\end{theorem}

post_theorem_intro_text:
Based on Theorem \ref{th:1.1}, we can also derive the following result for general weight functions $a(x)$ continuous and positive, not necessarily constant.

\begin{theorem}
\label{th:1.2}
Assume that $a(x)$ is continuous and positive in $[0,R]$. Then:
	\begin{enumerate}
		\item[{\rm (a)}] For every $\lambda\in\R$, \eqref{eq:1.1} possesses a minimal and a maximal positive solution, respectively denoted by $L^{\rm min}_{\lambda}$ and $L^{\rm max}_{\lambda}$, in the sense that any other positive solution $L$ of \eqref{eq:1.1} satisfies
	\begin{equation}
		\label{i.4}
		L^{\rm min}_{\lambda}(x) \leq L(x) \leq L^{\rm max}_{\lambda}(x) \quad \hbox{for all } x \in [0,R).
	\end{equation}
	\item[{\rm (b)}] As in Theorem \ref{th:1.1},
	\begin{equation}
		\label{i.5}
		\lim_{\lambda \uparrow +\infty} L^{\rm min}_{\lambda} = +\infty \;\;\hbox{uniformly in compact subsets of}\;\; [0,R),
	\end{equation}
unless  $\mathcal{B} = \mathcal{D}$ at $x=0$, in which case $L^{\rm min}_{\lambda}(0) = 0$ for all $\lambda \in \mathbb{R}$.
	\item[{\rm (c)}] As in Theorem \ref{th:1.1},
\begin{equation}
		\label{i.6}
		\lim_{\lambda \downarrow -\infty} L^{\rm max}_{\lambda} = 0 \;\; \hbox{uniformly in compact subsets of}\;\; [0,R).
	\end{equation}
\item[{\rm (d)}] If, in addition, $a$ is non-increasing in $[0,R]$, $\lambda \geq 0$ and $\mathcal{B} \in \{ \mathcal{D}, \mathcal{N}, \mathcal{R}_\beta : \beta <0 \}$, we have that $L^{\rm min}_{\lambda} = L^{\rm max}_{\lambda}$. Thus, in such cases, \eqref{eq:1.1} has a unique positive solution.
\end{enumerate}
\end{theorem}

Therefore, except for the uniqueness of the positive solution, the point-wise behavior of the positive solutions of \eqref{eq:1.1} as $\lambda\uparrow +\infty$ and $\lambda\downarrow -\infty$ mimic the patterns of  Theorem \ref{th:1.1} with  $a(x)$ constant, though for $a(x)$ non-constant \eqref{eq:1.1} might have several positive solutions.
Theorem \ref{th:1.2} (d) delivers a new uniqueness result based on the monotonicity of $a(x)$, which is based on a sophisticated use of the maximum principle rather than on the analysis of the exact blow-up rate of the positive solutions at $R$, as it is usual in most of the existing uniqueness results (see \cite{LG15} and the
references therein, for an exhaustive survey on this issue).
\par
The distribution of this paper is the following. Section \ref{sec:2} delivers some preliminaries;  among them, the comparison principles that we will use throughout this paper. Section  \ref{sec:3} shows the existence and uniqueness parts of Theorem \ref{th:1.1}, which are based on a systematic use of phase plane techniques. The remaining properties of the large solution $L_\lambda$ will be established in Sections \ref{sec:4}--\ref{sec:6}. Finally, in Section \ref{sec:7}, we prove Theorem \ref{th:1.2} based on Theorem \ref{th:1.1} and some additional comparison principles.

