\end{equation}
\end{itemize}
\end{Definition}

Then for any $T' < T$,  there exists a small number $\delta_0>0$  such that for any Mach number $\delta<\delta_0$, there exists a family of initial data 
$$
(\rho_{\delta}^0,\m_{\delta}^0)\in C^0(\mathbb{T}^n)\times  L^2(\mathbb{T}^n)
$$
with the following properties.
\begin{itemize}
\item For any fixed $\delta>0$, there exist infinitely many weak solutions $(\rho_{\delta},\rho_{\delta}\widehat{{\bf v}}_{\delta})$ on $(0, T')$ to the rescaled compressible Euler equations
\begin{equation}
\label{scalling system 111}
\left\{
\begin{split}
