\[
\int_0^\infty \int_{\mathbb{T}^n} \left( \rho_{\delta} \, \partial_t \varphi + \rho_{\delta} \v_{\delta} \cdot \nabla \varphi \right) \, dx \, dt + \int_{\mathbb{T}^n} \rho_{\delta}^0(x) \varphi(0,x) \, dx = 0;
\]

 \item for any $\phi \in C^\infty_c(\mathbb{T}^n \times [0, T); \R^n)$,
\begin{equation*}
\begin{split}
\int^\infty_0 \int_{\mathbb{T}^n} \rho_{\delta} \v_{\delta} \cdot \partial_t \phi &+ \rho_{\delta} \v_{\delta} \otimes \v_{\delta} : \nabla \phi  \,dxdt +\int_0^\infty\int_{\mathbb{T}^n}\frac{\rho_{\delta}^{\gamma}}{\delta^2}\Dv \phi\,dx\,dt
\\&=  -\int_{\mathbb{T}^n}\m_{\delta}^0 \cdot \phi(\cdot, 0) \,dx.
\end{split}
\end{equation*}
\end{itemize}
\end{Definition}

\item The following asymptotic limits hold:
\begin{equation*}
\rho_{\delta}\to 1\;\;\;\text{ in } C^0([0,T']\times \mathbb{T}^n),\;\;\;\;\; \rho_{\delta}\widehat{{\bf v}}_{\delta}\to {\bf u} \;\text{ in } L^{2}(0,T';L^2(\mathbb{T}^n)),
\end{equation*}
and the initial data 
$$
\m_{\delta}^0\to {\bf u}^0\;\;\;\text{ weakly in }\;\; L^2(\mathbb{T}^n),
$$
as $\delta$ tends to zero.
\end{itemize}

ref_dict.prop:ldp-kernel:
\begin{proposition}[LDP for kernels and output] \label{prop:ldp-kernel}
Fix a depth $L \ge 1$, input $d_{\din}$ and output  $d_{\out}\ge 1$ dimensions, Lipschitz activation functions $(\sigma^{(\ell)})_{\ell=1,\ldots, L}$, and consider a sequence of MLPs outputs $f^{(L)}_{(n)}: \R^{d_{\din}} \to \R^{d_{\out}}$ with hidden layers widths $n_\ell = n_\ell(n)$ such that 
$$\lim_{n \to \infty} \frac{n_\ell}{n} := \beta^{(\ell)} \in (0, \infty] \quad \text{for every $\ell = 1, \ldots, L-1$.}$$
Let $\cX := \cur{x_i}_{i=1}^k  \subseteq \R^{d_{\din}}$ be fixed input points and consider the random (post-activation) kernels $v^{(\ell)}(\cX)_{(n)}$ defined as in \eqref{eq:v-def}. Then, 
\begin{enumerate}
\item [(i)] for every $\ell=0, 1, \ldots, L-1$, the LDP holds for $(v^{(\ell)}_{(n)}(\cX))_{n=1}^\infty$ with speed $n$ and rate function recursively defined as $I^{(0)}(v) := \infty 1_{\cur{v\neq v^{(0)}(\cX) }}$ and
$$ I^{(\ell)}(v) := \inf_{q \in \R^{k \times k}_{\succeq 0}}\Big\{ \beta^{(\ell)} J^{(\ell)}(v | q) + I^{(\ell-1)}(q)\Big\}, \quad \text{for $\ell = 1, \ldots, L-1$};$$
\item [(ii)] the LDP holds for $\bra{ \frac 1 {\sqrt{n}} f^{(L)}_{(n)}(\cX)}_{n=1}^\infty$ with speed $n$ and rate function
\begin{equation}\label{eq:rate-out-finite} I^{(L)}_{\cX, \out}( (z_i)_{i=1}^k ) := \inf_{q \in \R^{k \times k}_{\succeq 0}} \Big\{\sum_{i=1}^k \frac 1 2  \nor{z_i}_q^2  + I^{(L-1)}(q)\Big\}.\end{equation}
\end{enumerate}
\end{proposition}

ref_dict.thm:schied:
\begin{theorem}[Exponential tightness criterion]
\label{thm:schied}
Let $Z_n=(Z_n(x))_{x\in [0,1]^d}$, $n\geq 1$, be a sequence of stochastic processes taking values in $\R^k$, with continuous sample paths. 

The sequence $(Z_n)_{n =1}^\infty$ is exponentially tight in $C([0,1]^d,\mathbb R^k)$,  endowed with the topology of uniform convergence, with speed $n$, if there exist $\bar{n} \in \mathbb{N}$,  $\alpha>0$, $\cost < \infty$ such that, for all $x,y \in [0,1]^d$ with $x \neq y$,
\begin{equation}\label{eq:schied-increments}
\sup_{n\ge \bar{n}} \frac {1}{n} \log \EE\sqa{ \bra{1+ \frac{|Z_n(x)- Z_n(y)| }{|x-y|^{\alpha} }}^{n}} \le \cost 
\end{equation}
and 
\begin{equation}\label{eq:schied-zero} \sup_{n \ge \bar{n}} \frac {1}{n} \log \EE\sqa{ \bra{1+ \abs{Z_n(0)} }^{n} }\le \cost. \end{equation}
\end{theorem}

post_theorem_intro_text:
The proof relies on an inductive argument on the number of layers, combining Cram\'er's theorem for empirical means of i.i.d.\ random variables with a careful analysis of the continuity properties of the neural network architecture. The high-level structure is somewhat analogous to that of the functional CLT for MLPs presented in \cite{bracale_large-width_2020}, of course, with modifications to account for the different nature of large deviations. In brief:
\begin{enumerate}
\item[(i)] In Section~\ref{sec:exp-tight} we establish exponential tightness of the sequence $(\frac{1}{\sqrt{n}} f^{(L)}_{(n)}(\cdot))_{n\geq 1}$ on $C(\mathcal{X},\mathbb{R}^{d_{out}})$, endowed with the uniform topology.
In particular, we use a variant of Schied's criterion \cite{schied1994criteria,schied1997moderate}, Theorem~\ref{thm:schied}, tailored to the layer-by-layer propagation of randomness and taking into account the sub-linear growth of activation functions. 

\item[(ii)] In Section \ref{sec:ldp-finite} we first prove that for a fixed finite set of inputs, the LDP for the corresponding finite-dimensional network outputs holds. This step relies on Chaganty's lemma \cite{chaganty1997large}, combined with exponential equivalence arguments, and Cram\'er's theorem under local exponential moment assumptions. The overall strategy is close in spirit to the recent contribution by Vogel \cite{vogel2025large}, although our argument crucially relies on epi-convergence techniques from convex analysis.\footnote{Precisely, we exploit epi-convergence techniques to establish the joint lower semi-continuity of a suitable function, filling a gap in Vogel's argument contained in \cite[Lemma 2.2]{vogel2025large}, and precisely implication (2.11) therein. To argue that this implication can not hold in general, one considers e.g. the scalar (one-dimensional) case, $\sigma(x)=\max\{0,x\}+\eta$, $x\in\mathbb R$, $\eta\neq 0$, $q=0$ and $q_n>0$ for every $n$. Then, for any fixed $\varepsilon>0$ and $n$, for $\eta$ sufficiently small the inequality (2.11) in \cite{vogel2025large} is false on an event of positive probability.} 

\item[(iii)] To conclude (see the argument after the proof of Proposition \ref{prop:ldp-kernel}), we lift the finite-input LDPs to an LDP for the entire process by means of a standard application of the Dawson--G\"artner theorem and the inverse contraction principle.

\end{enumerate}

\subsection{Relation to the literature.}

The work of three of the authors of this paper \cite{macci2024large}, primarily established an LDP for the output of MLPs with bounded activations and finite input sets. Functional
LDPs for MLPs obtained so far have been limited to settings with Gaussian weights and growth assumptions on the activation function, which exclude the ReLU \cite{andreis2025ldp}. The recent work \cite{vogel2025large} addresses large deviations for Gaussian networks with ReLU activation, but focuses on a finite set of inputs. To the best of our knowledge, a functional LDP for deep neural networks with general Lipschitz activations has not been previously established.

\subsection{Perspectives}

The results of this work suggest several natural directions for future research. First, the recursive  structure of rate functions is compatible with more general architectures and could potentially be combined with the tensor-program framework of \cite{yang_wide_2019} to treat convolutional, residual, or attention-based networks.  

Second, the probabilistic techniques developed in this paper provide a natural starting point for the study of large deviations during training, where the dynamics of the parameters introduce additional temporal dependence and non-equilibrium effects. Establishing LDPs for training dynamics remains a largely open problem; in this context, some specific aspects, in the case of one-hidden-layer neural networks, are investigated in \cite{HirschWillhalm}.

