ref_dict.cor_faltings-height-cyclotomic:
\begin{Cor}\label{cor_faltings-height-cyclotomic}
		Let $n\ge 3$ be an odd integer and let $A_n$ be an abelian variety having complex multiplication by the canonical CM type $(\mathbb{Q}(\zeta_n),\Sigma_n)$. The stable Faltings height of $A_n$ is bounded from above by
		\begin{align*}
		h_{\mathrm{Fal}}(A_n)< \tfrac{n}{8}\log n+\tfrac{9}{64}n\log\log n-0.136n. 
		\end{align*}
	\end{Cor}

ref_dict.thm_faltings-height-hyperelliptic:
\begin{Thm}\label{thm_faltings-height-hyperelliptic}
		Let $X_n$ be the hyperelliptic curve defined by the equation $y^2=x^n-1$ for any odd integer $n\ge 3$. We write $g=\frac{n-1}{2}$ for its genus. The stable Faltings height of $X_n$ is given by
		\begin{align*}
			h_{\mathrm{Fal}}(X_n)=&\tfrac{n}{8}\sum_{\substack{p\text{ prime}\\ p\mid n}}\frac{p^{2\mathrm{ord}_{p}(n)}-1}{p^{2\mathrm{ord}_{p}(n)-1}(p^2-1)}\log p+\tfrac{n}{8}\log n-\tfrac{g}{2}\log \pi+\tfrac{g}{2n}\log 2\\
			&-\sum_{j=1}^g\log\frac{\Gamma\left(\frac{2j-1}{2n}\right)}{\Gamma\left(\frac{1}{2}+\frac{2j-1}{2n}\right)}.
		\end{align*}
	\end{Thm}

ref_dict.rem_CM:
\begin{Rem}\label{rem_CM}
		If $n=p\ge 3$ is a prime, then it holds $$\dim \mathrm{Jac}(X_p)=\frac{p-1}{2}=\frac{\varphi(p)}{2}=\dim A_p$$ for the abelian subvariety $A_p\subseteq \mathrm{Jac}(X_p)$ in Lemma \ref{lem_subvariety}. This implies $A_p=\mathrm{Jac}(X_p)$. Thus, $\mathrm{Jac}(X_p)$ has complex multiplication by the CM type $(\mathbb{Q}(\zeta_p),\Sigma_p)$. A theorem by Colmez \cite[Theorem 0.3 (ii)]{Col93} states that the Faltings height $h_{\mathrm{Fal}}(\mathrm{Jac}(X_p))$ only depends on the CM type $(\mathbb{Q}(\zeta_p),\Sigma_p)$. Thus, Theorem \ref{thm_faltings-height-hyperelliptic} gives an explicit expression for the stable Faltings height of any abelian variety having complex multiplication by the CM type $(\mathbb{Q}(\zeta_p),\Sigma_p)$ for any prime $p\ge 3$.
	\end{Rem}

ref_dict.thm:intro-general:
\begin{theorem}\label{thm:intro-general}
Let $c > 0$ be given.
	For each $N$, let $(w_1, \dots, w_N)$ have the symmetric Dirichlet distribution with parameter $c/N$ and be independent of  random variables $\lambda_1, \dots, \lambda_N$. Assume that the empirical distribution $L_N = N^{-1} \sum_{i=1}^N \delta_{\lambda_i}$ converges weakly to a limiting probability measure $\rho$ as $N \to \infty$, in probability. Then the random probability measure (the spectral measure) 
\[
