\label{thm:conv}
		Let f be a biholomorphism of form \eqref{eq:f} and such that for all $i \in \{1, \ldots, n\}$, we have $\Ree \left(\frac{a_i}{\langle a,M \rangle} \right) > 0$. Then in any neighbourhood of the origin there exists $d$ pairwise disjoint connected open sets $\Omega^{+}_0, \ldots, \Omega^{+}_{d-1}$ with $0 \in \partial \Omega^+_k$ for all $k$ and  $d$ pairwise disjoint connected open sets $\Omega^{-}_0, \ldots, \Omega^{-}_{d-1}$ with $0 \in \partial \Omega^-_k$ for all $k$, such that the following assertions hold:
		\begin{enumerate}
			\item The sets $\Omega^+_k$ are invariant by $f$ and $f^{\circ j} \to 0$ as $j \to +\infty$ compactly on $\Omega^+_k$ for all k, and the sets $\Omega^-_k$ are invariant by $f^{-1}$ and $f^{\circ -j} \to 0$ as $j \to +\infty$ compactly on $\Omega^-_k$ for all k.
			\item The sets $\Omega^{+}_0, \ldots, \Omega^{+}_{d-1}, \Omega^{-}_0, \ldots, \Omega^{-}_{d-1}$ together with the fixed set $\{\mathbf{x}^M = 0\}$ form a neighbourhood of the origin.
			\item For each $k$, there exists biholomorphisms $\phi^+_k : \Omega^+_k \to W^+_k \in \mathbb{C}^n$ and $\phi^-_k : \Omega^-_k \to W^-_k \in \mathbb{C}^n$ with the following properties :
			\begin{itemize}
				\item $\phi^+_k$ and $\phi^-_k$ conjugate $f$ to $(z, w_1, \ldots, w_{n-1}) \to (z+1, w_1, \ldots, w_{n-1})$,
				\item the sets $W^+_k$ and $W^-_k$ satisfy:
				$$
				\bigcup_{\pm j \in \mathbb{N}} T_j \left(W^{\pm}_k \right)= \mathbb{C} \times (\mathbb{C}^*)^{n-\bar{m}-1} \times \mathbb{C}^{\bar{m}}.
				$$
			\end{itemize}
		\end{enumerate}

