\begin{prop}\label{prop:psi_I}
		The sequence $\left(g_I (f^{\circ j} (\x))\right)_j$ converges uniformly on $U_0$ to a holomorphic function $\psi_I$ invariant by $f$. Moreover there exists $u_I$ holomorphic such that $\psi_I = g_I u_I$ and $u_I - 1 = O (\abs{\x^m}^{\gamma})$.
	\end{prop}

ref_dict.thm:div:
\begin{mainthm}\label{thm:div}
		Let f be a biholomorphism of form \eqref{eq:f} such that there exists $i \in \{1, \ldots, n\}$ such that $\Ree \left(\frac{a_i}{\aM} \right) < 0$.
		Then there exists a neighbourhood $U$ of the origin such that for any $p \in U$ outside of the fixed point set, there exists $j \in \NN$ such that $f^{\circ j} (p) \notin U$ and $j' \in \NN$ such that $f^{\circ -j'} (p) \notin U$.
	\end{mainthm}

