ref_dict.convergence:
\begin{theorem}[Smooth convergence]\label{convergence}
    Let $\hat \omega$, $\hat \alpha$ be a K\"ahler metric and a closed $(1, 1)$-form satisfying $-c_1(X) + \lambda [\hat \omega] + [\hat \alpha] = 0$ with $\lambda \leq 0$, and assume that $[\hat \omega]$ contains at most one cscK metric. If the system \eqref{system1}, \eqref{system2} satisfies an a priori estimate of the form $C^{-1} \hat \omega \leq \omega(t) \leq C \hat \omega$, then it has a unique solution on $[0, \infty)$ which converges smoothly to the unique cscK metric $\omega_\infty$ in $[\hat \omega]$ and the unique $\omega_\infty$-harmonic $(1, 1)$-form $\alpha_\infty$ in $[\hat \alpha]$.
\end{theorem}

ref_dict.KEconvergence:
\begin{theorem}[Smooth convergence to KE metric]\label{KEconvergence}
    Assume $c_1(X) < 0$. Let $\hat \omega$ be a K\"ahler metric satisfying $-c_1(X) + \lambda [\hat \omega] = 0$ with $\lambda < 0$. The equation
    \begin{equation*}
        \frac{\omega - \hat \omega}{t} = -\Ric(\omega) + \lambda \omega
    \end{equation*}
    has a unique solution on $[0, \infty)$ which converges smoothly to the unique K\"ahler-Einstein metric $\omega_\infty$ in $[\hat \omega]$.
\end{theorem}

ref_dict.conformalestimates:
\begin{lemma}[A priori estimates for conformal factors]\label{conformalestimates}
    Let $X$ be a Riemann surface, $\hat \omega$ a K\"ahler metric, $\hat \alpha$ a closed $(1, 1)$-form, $\lambda = \int_X (c_1(X) - A) / \int_X [\hat \omega]$, and assume that $\hat \tau \maxx^+ - \hat \tau \minn^- < -\hat R \maxx$. Let $\phi(t)$, $\tau(t)$ be functions, set $\omega(t) = e^{\phi(t)} \hat \omega$, $\alpha(t) = \tau(t) \omega(t)$, and assume that $\phi(t)$, $\tau(t)$ solve \eqref{conformalsystem1b}, \eqref{conformalsystem2a} with $\phi(0) = 0$ on $[0, T)$ for some $T \in (0, \infty]$. Then $\lambda < 0$ and
    \begin{equation}\label{conformalestimates1}
        \| \phi(t) \|_{C^0} \leq C, \quad \| \tau(t) \|_{C^0} \leq C
    \end{equation}
    so
    \begin{equation}\label{conformalestimates2}
        C^{-1} \hat \omega \leq \omega(t) \leq C \hat \omega, \quad -C \omega(t) \leq \alpha(t) \leq C \omega(t)
    \end{equation}
    and also
    \begin{equation}\label{conformalestimates3}
        \| R(t) \|_{C^0} \leq C \left( 1 + \frac{1}{t} \right).
    \end{equation}
\end{lemma}

ref_dict.riemannsurfacesconvergencefromclass:
\begin{theorem}[Smooth convergence on Riemann surfaces]\label{riemannsurfacesconvergencefromclass}
    Let $X$ be a Riemann surface with $c_1(X) < 0$, $A \in H^{1,1}(X, \mathbb{R})$ and $\hat \omega$ a K\"ahler metric satisfying \ref{A1}. Then there is an open set of $\hat \alpha \in A$ in the topology of the uniform norm for which the system \eqref{system1}, \eqref{system2} has a unique solution on $[0, \infty)$ which converges smoothly to the unique cscK metric $\omega_\infty$ in $[\hat \omega]$ and the unique $\omega_\infty$-harmonic $(1, 1)$-form $\alpha_\infty$ in $A$.
\end{theorem}

post_theorem_intro_text:
\begin{remark}\label{convergencewhenc1negative}
    If $c_1(X) < 0$ and $\hat \omega \in -r c_1(X)$ for some $r > 0$ or $c_1(X) = 0$ then the hypothesis that $[\hat \omega]$ contains at most one cscK metric is satisfied, since in these cases cscK metrics are K\"ahler-Einstein and are unique in their classes.
\end{remark}

\noindent Combining the above remark with uniform estimates on the family of metrics, we use a special case of the system to show smooth convergence to the unique K\"ahler-Einstein metric in $\frac{1}{\lambda} c_1(X)$, giving an alternative proof of existence:

\begin{theorem}[Smooth convergence to KE metric]\label{KEconvergence}
    Assume $c_1(X) < 0$. Let $\hat \omega$ be a K\"ahler metric satisfying $-c_1(X) + \lambda [\hat \omega] = 0$ with $\lambda < 0$. The equation
    \begin{equation*}
        \frac{\omega - \hat \omega}{t} = -\operatorname{Ric}(\omega) + \lambda \omega
    \end{equation*}
    has a unique solution on $[0, \infty)$ which converges smoothly to the unique K\"ahler-Einstein metric $\omega_\infty$ in $[\hat \omega]$.
\end{theorem}

\noindent In the case of Riemann surfaces of genus at least $2$ which are exactly those with negative first Chern class, we show that solutions to the system starting from more general initial data will smoothly converge to the unique K\"ahler-Einstein metric:

\begin{theorem}[Smooth convergence on Riemann surfaces]\label{riemannsurfacesconvergencefromclass}
    Let $X$ be a Riemann surface with $c_1(X) < 0$, $A \in H^{1,1}(X, \mathbb{R})$ and $\hat \omega$ a K\"ahler metric satisfying \ref{A1}. Then there is an open set of $\hat \alpha \in A$ in the topology of the uniform norm for which the system \eqref{system1}, \eqref{system2} has a unique solution on $[0, \infty)$ which converges smoothly to the unique cscK metric $\omega_\infty$ in $[\hat \omega]$ and the unique $\omega_\infty$-harmonic $(1, 1)$-form $\alpha_\infty$ in $A$.
\end{theorem}

\noindent The technical assumption \ref{A1} is needed for the $C^0$ estimates for $\omega$ and $\alpha$ \eqref{conformalestimates}. This theorem is similar to a result of Fei-Guo-Phong \cite{fei2019convergence}, where the assumption \eqref{A1} is not needed, but $\kappa \neq 1$ is assumed.

This paper is organized as follows. In \cref{section:preliminaries}, we introduce the notation and basic facts that we will use throughout the paper. In \cref{section:thecoupledcontinuityequations}, we introduce the system of elliptic equations, prove its short-time existence, identify its stationary points and prove a scalar curvature lower bound. In \cref{section:reductiontoascalarsystem}, we show that the system reduces to a scalar system involving the complex Monge-Amp\`ere equation, and use this to obtain estimates on potentials. In \cref{section:higherorderestimatesandconvergence}, contingent on a uniform estimate for $\omega$, we prove higher order estimates and smooth convergence to a cscK metric and harmonic $(1, 1)$-form whenever there is a unique cscK metric in the K\"ahler class of the initial metric, proving \cref{convergence}. In \cref{section:kahlereinsteinmetrics}, we establish the required uniform estimate for $\omega$ in a special case by proving a $C^2$ estimate for potentials, which allows us to demonstrate an application of the preceeding convergence theorem and giving a proof of \cref{KEconvergence}. In \cref{section:riemannsurfaces}, we analyze the case of Riemann surfaces and establish the uniform estimate for $\omega$ by estimating conformal factors and demonstrate another application of the convergence theorem, giving a proof of \cref{riemannsurfacesconvergencefromclass}.\\

\noindent\textbf{Acknowledgements:} We would like to thank Teng Fei and Ben Weinkove for some helpful discussions.

