ref_dict.ModThe:
\begin{prop}[Modulation theory]\label{ModThe}
Let $b\in(0,1)$ and $u:I\times \mathbb{R}^3\to \mathbb{C}$ be a $H^1$-solution to \eqref{INLS} with initial datum satisfying $M[u_0]=M[Q]$ and $E[u_0]=E[Q]$. For $\delta_0>0$ define
$$
I_0=\{t\in I: \delta(t)<\delta_0\}.
$$
Then, for small enough $\delta_0$, there exist functions $\zeta: I_0\to \mathbb{R}$, $\alpha: I_0\to \mathbb{R}$, $h: I_0\to H^1$ such that
$$
g(t)=e^{-i(\zeta(t)+t)}u(t)- Q =\alpha(t)Q+h(t), 
$$
with
\begin{equation}\label{alpha2}
\|h(t)\|_{H_x^1}\sim |\alpha(t)|\sim \delta(t), \quad  |\dot\zeta(t)| \lesssim \delta(t),
\end{equation}
and
\begin{equation}\label{nablag}
\|g(t)\|_{H_x^1} \lesssim \delta(t).
\end{equation}
\end{prop}

ref_dict.thm:threshold:
\begin{thm}[Classification of threshold dynamics, \cite{CM23}]\label{thm:threshold}
Let $u_{0}\in H^{1}(\mathbb{R}^3)$ satisfying \eqref{threshold} and $u$ be the corresponding solution of \eqref{INLS}. We have the following

\begin{itemize}
\item[(i)] If
\[
\|u_{0}\|_{L_x^{2}}^{1-s_{c}} \|\nabla u_{0}\|_{L_x^{2}}^{s_{c}}
   < \|Q\|_{L_x^{2}}^{1-s_{c}} \|\nabla Q\|_{L_x^{2}}^{s_{c}},
\]
then $u$ either scatters as $t\to\pm\infty$ or $u=Q^{-}$ up to the symmetries of the equation.

\item[(ii)] If
\[
\|u_{0}\|_{L_x^{2}}^{1-s_{c}} \|\nabla u_{0}\|_{L_x^{2}}^{s_{c}}
   = \|Q\|_{L_x^{2}}^{1-s_{c}} \|\nabla Q\|_{L_x^{2}}^{s_{c}},
\]
then $u = e^{it}Q$ up to the symmetries of the equation.

\item[(iii)] If
\[
\|u_{0}\|_{L_x^{2}}^{1-s_{c}} \|\nabla u_{0}\|_{L_x^{2}}^{s_{c}}
   > \|Q\|_{L_x^{2}}^{1-s_{c}} \|\nabla Q\|_{L_x^{2}}^{s_{c}}
\]
and $u_{0}$ is radial or $xu_{0}\in L_x^{2}(\mathbb{R}^{3})$, then $u$ either blows up in finite positive and negative times or $u=Q^{+}$ up to the symmetries of the equation.
\end{itemize}
\end{thm}

